using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Binary.Translations;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Plugins.Records;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Round 4 unknown-field evidence (world and quest), the high-confidence half:
// - INFO NAM9 ("Text Hash" in xEdit) is a Windows FILETIME: all 130,222 in Starfield.esm decode to 2016-2023, all in
//   Fallout4.esm to 2013-2015. Now the UInt64 CreationTime (GetCreationTimeUtc() gives the date).
// - QUST QSRD comes twice per stage complete data: a UInt32 count of reward entries, then an empty QSRD that ends
//   them (xEdit). Starfield.esm: 15,098 pairs; the counts add up to the 615 QRXP reward entries. Before, each pair was
//   split into two StageCompleteData items holding raw bytes.
// - Padding, renamed Unused and kept byte for byte: QUST INDX +3 (0xAB on 13,383 of 14,537), PACK PKDT +7 and +10,
//   PSDT +5, PFO2 +13, XOWN +4, XESP +5, XLIG +24 (0xABABABAB on 100,528 of 100,531), XPDD +13 (AB AB AB).
// - XPDD's last 4 bytes are a UInt8 (1 on 188,640 refs, 0 on 44) and 3 filler bytes (0xABABAB01 as a UInt32).
// - SCEN SPPQ is on all 993 scenes with speech challenge data and on no other (ChallengeDataMarker, checked in
//   SceneSpeechChallengeTests). REFR XLIB is xEdit's Leveled Item Base Object; WRLD NAM7 is xEdit's Water Material.
// Links: TROT VoiceType, QDUP, XPCK, XLIB and GNAM/JNAM/HNAM were already FormLinks; these tests check TROT and XLIB.
public class WorldQuestUnknownFieldTests
{
    private static byte[] WriteBack(IMajorRecordGetter rec) => Write(w => ((IBinaryItem)rec).WriteToBinary(w));

    // UC08SharedInfo01 (20617A:Starfield.esm)
    private const string Info = "45444944110055433038536861726564496E666F303100454E414D040000000000545244410C00FFFFFFFFA46094002322E24054524F540800D23A0100BDBB7B404E414D310400B0DA01004E414D320100004E414D330100004E414D340100004E414D390800F09EC8C5DFB6D6014E414D30010000494E414D040001000000";

    [Fact]
    public void Info_CreationTimeAndVoiceTypeLink()
    {
        foreach (var info in ReadBoth<IDialogResponsesGetter>(Record("INFO", Hex(Info)), f => DialogResponses.CreateFromBinary(f), (s, p) => DialogResponsesBinaryOverlay.DialogResponsesFactory(s, p)))
        {
            var r = info.Responses.ShouldHaveSingleItem();
            r.CreationTime.ShouldBe(0x01D6B6DFC5C89EF0UL);
            r.GetCreationTimeUtc().ShouldBe(new DateTime(2020, 11, 9, 21, 32, 6, 623, DateTimeKind.Utc));
            var trot = r.TROTs.ShouldHaveSingleItem();
            trot.VoiceType.FormKey.ShouldBe(new FormKey(TestModKey, 0x013AD2));
            trot.Duration.ShouldBe(BitConverter.ToSingle(Hex("BD-BB-7B-40")));
            info.EnumerateFormLinks().Select(l => l.FormKey).ShouldContain(new FormKey(TestModKey, 0x013AD2));
            GameConstants.Starfield.MajorRecord(WriteBack(info)).Content.ToArray().ShouldBe(Hex(Info));
        }
    }

    // FFNeonZ06 (082D5A:Starfield.esm): 16 stage complete datas; two hold an affinity change (NAM1 after the end
    // marker), two hold one reward each.
    private const string Neon = "";

    // FFParadisoZ03 (1C433F:Starfield.esm): 10 stage complete datas; one holds two rewards, each with a condition.
    private const string Paradiso = "";

    private static IEnumerable<IQuestGetter> ReadQuest(string hex)
        => ReadBoth<IQuestGetter>(Record("QUST", Hex(hex)), f => Quest.CreateFromBinary(f), (s, p) => QuestBinaryOverlay.QuestFactory(s, p));

    private static List<IQuestStageCompleteDataGetter> CompleteDatas(IQuestGetter q)
        => q.Stages.SelectMany(s => s.LogEntries).SelectMany(l => l.StageCompleteDatas).ToList();

    [Fact]
    public void Quest_RewardCountAndEndMarker_Neon()
    {
        foreach (var q in ReadQuest(Neon))
        {
            var datas = CompleteDatas(q);
            datas.Count.ShouldBe(16);
            datas.ShouldAllBe(d => d.RewardCount == (uint)d.RewardDatas.Count);
            datas.Count(d => d.RewardCount == 1).ShouldBe(2);
            datas.Where(d => !d.AffinityChange.IsNull).Select(d => d.AffinityChange.FormKey.ID).ShouldBe(new[] { 0x07D829u, 0x07D828u }, ignoreOrder: true);
            q.Stages.ShouldAllBe(s => s.FlagsUnused.ToArray().SequenceEqual(new byte[] { 0xAB }));
            GameConstants.Starfield.MajorRecord(WriteBack(q)).Content.ToArray().ShouldBe(Hex(Neon));
        }
    }

    [Fact]
    public void Quest_RewardCountAndEndMarker_Paradiso()
    {
        foreach (var q in ReadQuest(Paradiso))
        {
            var datas = CompleteDatas(q);
            datas.Count.ShouldBe(10);
            datas.ShouldAllBe(d => d.RewardCount == (uint)d.RewardDatas.Count);
            var two = datas.Single(d => d.RewardCount == 2);
            two.RewardDatas.Select(r => r.Rewards.Single().Item.FormKey.ID).ShouldBe(new[] { 0x026B0Fu, 0x026B10u });
            two.RewardDatas.ShouldAllBe(r => r.XpAwarded.FormKey.ID == 0x0DF3E7u && r.Conditions.Count == 1);
            GameConstants.Starfield.MajorRecord(WriteBack(q)).Content.ToArray().ShouldBe(Hex(Paradiso));
        }
    }

    private static IEnumerable<IPackageGetter> ReadPackage(string hex)
        => ReadBoth<IPackageGetter>(Record("PACK", Hex(hex)), f => Package.CreateFromBinary(f), (s, p) => PackageBinaryOverlay.PackageFactory(s, p));

    // CF06_JiNashida_SitAtFrontDesk (001BD7:Starfield.esm): PKDT +7 is FF
    private const string JiNashida = "";
    // SQ_CCT_Enviro_Gassy_9 (092CAC:Starfield.esm): PKDT +10 is 04 00
    private const string Gassy = "";
    // UC05_Balmor_ActivateCodeMachine_Stage796 (0C0AB6:Starfield.esm): PSDT +5 is 02 00 00
    private const string Balmor = "";
    // Activate (07976C:Starfield.esm): a template with a flags override (PFO2)
    private const string Activate = "";

    [Fact]
    public void Package_PaddingKept()
    {
        foreach (var p in ReadPackage(JiNashida))
        {
            p.PreferredSpeedUnused.ToArray().ShouldBe(new byte[] { 0xFF });
            p.InterruptFlagsUnused.ToArray().ShouldBe(new byte[] { 0, 0 });
            GameConstants.Starfield.MajorRecord(WriteBack(p)).Content.ToArray().ShouldBe(Hex(JiNashida));
        }
        foreach (var p in ReadPackage(Gassy))
        {
            p.InterruptFlagsUnused.ToArray().ShouldBe(new byte[] { 4, 0 });
            GameConstants.Starfield.MajorRecord(WriteBack(p)).Content.ToArray().ShouldBe(Hex(Gassy));
        }
        foreach (var p in ReadPackage(Balmor))
        {
            p.ScheduleMinuteUnused.ToArray().ShouldBe(new byte[] { 2, 0, 0 });
            GameConstants.Starfield.MajorRecord(WriteBack(p)).Content.ToArray().ShouldBe(Hex(Balmor));
        }
        foreach (var p in ReadPackage(Activate))
        {
            var o = p.ProcedureTree.Select(b => b.FlagsOverride).First(x => x != null)!;
            o.PreferredSpeedUnused.ToArray().ShouldBe(new byte[] { 0, 0, 0 });
            GameConstants.Starfield.MajorRecord(WriteBack(p)).Content.ToArray().ShouldBe(Hex(Activate));
        }
    }

    private static IEnumerable<IPlacedObjectGetter> ReadRefr(params byte[][] subs)
        => ReadBoth<IPlacedObjectGetter>(Record("REFR", subs), f => PlacedObject.CreateFromBinary(f), (s, p) => PlacedObjectBinaryOverlay.PlacedObjectFactory(s, p));

    private static void SubrecordWritesBack(IPlacedObjectGetter refr, string type, string hex)
        => GameConstants.Starfield.MajorRecord(WriteBack(refr)).FindSubrecord(new RecordType(type)).Content.ToArray().ShouldBe(Hex(hex));

    [Fact]
    public void ProjectedDecal_ByteAndFiller()
    {
        // REFR 2B2D8C (Starfield.esm), base proj_DecalSubtleGrunge09 (1F5688:Starfield.esm): byte 1
        const string on = "0000803F0000803F9A99193F01ABABAB";
        foreach (var refr in ReadRefr(Subrecord("XPDD", on)))
        {
            var d = refr.ProjectedDecal!;
            d.WidthScale.ShouldBe(1f);
            d.UnknownFloat.ShouldBe(0.6f);
            d.UnknownByte.ShouldBe((byte)1);
            d.UnknownByteUnused.ToArray().ShouldBe(Hex("AB-AB-AB"));
            SubrecordWritesBack(refr, "XPDD", on);
        }
        // REFR 0B6601 (Starfield.esm), base proj_DecalSubtleScratches01b (1F5685:Starfield.esm): byte 0
        const string off = "9A99993E9A99993E0000803F00ABABAB";
        foreach (var refr in ReadRefr(Subrecord("XPDD", off)))
        {
            refr.ProjectedDecal!.UnknownByte.ShouldBe((byte)0);
            SubrecordWritesBack(refr, "XPDD", off);
        }
    }

    [Fact]
    public void Ownership_EnableParent_Padding()
    {
        // XOWN of REFR 1FDD1A (Starfield.esm)
        const string xown = "1D9601000000000000A50C00";
        // XESP of REFR 26C649 (Starfield.esm)
        const string xesp = "4C650F0000000000";
        foreach (var refr in ReadRefr(Subrecord("XOWN", xown), Subrecord("XESP", xesp)))
        {
            refr.Ownership!.Owner.FormKey.ID.ShouldBe(0x01961Du);
            refr.Ownership.OwnerUnused.ToArray().ShouldBe(new byte[4]);
            refr.Ownership.NoCrimeUnused.ToArray().ShouldBe(Hex("A5-0C-00"));
            refr.EnableParent!.Reference.FormKey.ID.ShouldBe(0x0F654Cu);
            refr.EnableParent.FlagsUnused.ToArray().ShouldBe(new byte[3]);
            SubrecordWritesBack(refr, "XOWN", xown);
            SubrecordWritesBack(refr, "XESP", xesp);
        }
    }

    [Fact]
    public void LeveledItemBaseObject_IsALink()
    {
        // REFR 010154 (sfta02.esm): NAME and XLIB both point at 1CCF46 (Starfield.esm)
        foreach (var refr in ReadRefr(Subrecord("NAME", "46CF1C00"), Subrecord("XLIB", "46CF1C00")))
        {
            refr.LeveledItemBaseObject.FormKey.ShouldBe(new FormKey(TestModKey, 0x1CCF46));
            refr.EnumerateFormLinks().Count(l => l.FormKey == new FormKey(TestModKey, 0x1CCF46)).ShouldBe(2);
            SubrecordWritesBack(refr, "XLIB", "46CF1C00");
        }
    }

    [Fact]
    public void Worldspace_WaterMaterial()
    {
        // LC167World (1477F8:Starfield.esm)
        const string nam7 = "446174615C4D4154455249414C535C57617465725C576174657243616C6D2E6D617400";
        foreach (var world in ReadBoth<IWorldspaceGetter>(Record("WRLD", Subrecord("NAM7", nam7)), f => Worldspace.CreateFromBinary(f), (s, p) => WorldspaceBinaryOverlay.WorldspaceFactory(s, p)))
        {
            world.WaterMaterial.ShouldBe(@"Data\MATERIALS\Water\WaterCalm.mat");
            GameConstants.Starfield.MajorRecord(WriteBack(world)).FindSubrecord(new RecordType("NAM7")).Content.ToArray().ShouldBe(Hex(nam7));
        }
    }
}
